function auditChangesText(detail: string): string {
  if (!detail) return '';
  try {
    const parsed = JSON.parse(detail);
    if (Array.isArray(parsed.changes)) {
      return parsed.changes.map((change: Record<string, unknown>) => {
        const from = change.from === undefined || change.from === null || change.from === '' ? '∅' : String(change.from);
        const to = change.to === undefined || change.to === null || change.to === '' ? '∅' : String(change.to);
        const extra = change.rotated === undefined ? '' : change.rotated ? '（密钥已更换）' : '（密钥未更换）';
        return `${String(change.field || '')}: ${from} → ${to}${extra}`;
      }).join('；');
    }
    return JSON.stringify(parsed);
  } catch {
    return detail;
  }
}
