async function api<T>(path: string, auth: string, options: RequestInit = {}) {
  try {
    const headers = new Headers(options.headers);
    if (auth.startsWith('Basic ')) headers.set('Authorization', auth);
    const response = await fetch(path, { ...options, headers, credentials: 'same-origin', cache: 'no-store' });
    if (!response.ok) {
      const raw = await response.text();
      try {
        const detail = JSON.parse(raw) as { statusCode?: string; message?: string };
        if (response.status === 401) throw new Error(`${detail.statusCode || 'AUTHENTICATION_FAILED'}：${detail.message || '账号或密码错误'}`);
        throw new Error(`${detail.statusCode || `HTTP_${response.status}`}：${detail.message || '请求处理失败'}`);
      } catch (error) {
        if (error instanceof Error && error.message.includes('：')) throw error;
        throw new Error(`HTTP_${response.status}：${raw || '请求处理失败'}`);
      }
    }
    return response.status === 204 ? undefined as T : response.json() as Promise<T>;
  } catch (error) {
    if (error instanceof Error && error.message !== 'Failed to fetch') throw error;
    throw new Error(`NETWORK_ERROR：无法连接后端服务，请确认 8080 端口服务已启动（请求：${path}）`);
  }
}
function uploadRequest<T>(path: string, auth: string, body: FormData, onProgress: (loaded: number, total: number) => void) { return new Promise<T>((resolve, reject) => { const request = new XMLHttpRequest(); request.open('POST', path); request.withCredentials = true; if (auth.startsWith('Basic ')) request.setRequestHeader('Authorization', auth); request.upload.onprogress = event => { if (event.lengthComputable) onProgress(event.loaded, event.total); }; request.onerror = () => reject(new Error('UPLOAD_CONNECTION_LOST：上传连接中断，请检查网络后重试')); request.onload = () => { if (request.status < 200 || request.status >= 300) { try { const detail = JSON.parse(request.responseText) as { statusCode?: string; message?: string }; return reject(new Error(`${detail.statusCode || `HTTP_${request.status}`}：${detail.message || '上传失败'}`)); } catch { return reject(new Error(`HTTP_${request.status}：${request.responseText || '上传失败'}`)); } } try { resolve(JSON.parse(request.responseText) as T); } catch { reject(new Error('INVALID_UPLOAD_RESPONSE：上传响应格式异常')); } }; request.send(body); }); }
