const bytes = (value = 0) => value > 1024 ** 3 ? `${(value / 1024 ** 3).toFixed(1)} GB` : `${Math.ceil(value / 1024 ** 2)} MB`;
function outlineAssessmentRows(nodes: StandardOutlineNode[], path: string[] = []): { path: string; weight: number | null; knowledge: string; point: LevelAssessmentPoint }[] {
  return nodes.flatMap(node => {
    const current = [...path, `${node.code ? `${node.code} · ` : ''}${node.name}`];
    return [
      ...(node.assessmentPoints || []).map(point => ({ path: current.join(' / '), weight: node.weight, knowledge: node.relatedKnowledgeRequirement, point })),
      ...outlineAssessmentRows(node.children || [], current)
    ];
  });
}

